import axios from 'axios';

// API ve Debug ayarları
const API_BASE_URL = process.env.REACT_APP_API_URL || 'http://localhost:3001/api';
const DEBUG_MODE = process.env.NODE_ENV !== 'production';

// LCM ile görsel oluşturma servisi
export const getCombinedAuraDataWithImage = async (
  auraType: string,
  username: string,
  answers: { [key: number]: string }
): Promise<any> => {
  if (DEBUG_MODE) console.log('[FRONTEND_LCM] getCombinedAuraDataWithImage çağrıldı:', { auraType, username });

  try {
    // URL oluştur
    const url = `${API_BASE_URL}/aura/combined-data`;

    if (DEBUG_MODE) {
      console.log('[FRONTEND_LCM] API isteği gönderiliyor:');
      console.log('[FRONTEND_LCM] URL:', url);
      console.log('[FRONTEND_LCM] Quiz tipi:', auraType);
      console.log('[FRONTEND_LCM] Kullanıcı adı:', username);
      console.log('[FRONTEND_LCM] Cevap sayısı:', Object.keys(answers).length);
    }

    // Backend'e istek gönder
    const response = await axios.post(url, {
      auraType,
      username,
      answers
    });

    if (DEBUG_MODE) {
      console.log('[FRONTEND_LCM] API yanıtı alındı:', 
        response.data?.imageUrl ? 'Görsel URL ile' : 'Görsel URL olmadan');
      
      if (response.data?.imageUrl) {
        console.log('[FRONTEND_LCM] Görsel URL:', response.data.imageUrl.substring(0, 50) + '...');
      }
    }

    return response.data;
  } catch (error) {
    console.error('[FRONTEND_LCM] Hata:', error);
    throw error;
  }
};
